INSERT INTO `events` (`id`, `judul_event`, `deskripsi`, `tanggal`, `tanggal_selesai`, `tanggal_mulai`, `slug`, `lokasi`, `banner`, `is_active`, `created_at`, `updated_at`, `harga`) VALUES (9,'Multaqo Sanawi','<p>Hadirilah</p>','04/10/2023 - 04/10/2023','2023-10-04','2023-10-04','','PP. Darussa\'adah','image/event/QBUaR8AR8ZnLf50L28P8hh9Its6mejR7EvwlHZgK.png','0',NULL,'2023-10-25 20:02:33','Rp. 100.000'),
(10,'Multaqo Sanawi 7','<p>KABAR GEMBIRA&nbsp;</p>\r\n\r\n<p>HADIRILAH!!!<br />\r\nMULTAQO SANAWI 7&nbsp;<br />\r\nPertemuan Internasional Alumni Pondok Pesantren DARUSSAADAH AL ISLAMY li Sayyidil Walid Abuya Nur Hasanuddin Bin Abdul Latief&nbsp;</p>\r\n\r\n<p>Yang insyaallah akan di laksanakan pada :<br />\r\nHari : Sabtu &amp; Ahad<br />\r\nTgl : 04-05 November 2023</p>\r\n\r\n<p>Mari jangan menunggu waktu luang tapi kita luangkan waktu dan kita prioritas kan wafa&rsquo; kita kepada guru kita&nbsp;</p>\r\n\r\n<p>الله يوفقكم و يبارك فيكم&nbsp;<br />\r\nSemoga kita mendapatkan keberkahan daripada guru semua , Amiiiiiinnn</p>\r\n\r\n<p>SHARE&nbsp;SERENTAK</p>','01/07/2024 - 08/07/2024','2024-07-08','2024-07-01','MultaqoSanawi7','Masjid Darussa\'adah Kampus 1','image/event/4XZt4V8dkhJH6i2f1jmTJXCoqrS9gSaIgiOp2Bar.jpg','1',NULL,'2024-06-24 06:47:38','Rp. 100.000'),
(11,'Multaqo Sanawi 8','<p>KABAR GEMBIRA&nbsp;</p>\r\n\r\n<p>HADIRILAH!!!<br />\r\nMULTAQO SANAWI 8&nbsp;<br />\r\nPertemuan Internasional Alumni Pondok Pesantren DARUSSAADAH AL ISLAMY li Sayyidil Walid Abuya Nur Hasanuddin Bin Abdul Latief&nbsp;</p>\r\n\r\n<p>Yang insyaallah akan di laksanakan pada :<br />\r\nHari : Sabtu &amp; Ahad<br />\r\nTgl : 19-20 Oktober 2023</p>\r\n\r\n<p>Mari jangan menunggu waktu luang tapi kita luangkan waktu dan kita prioritas kan wafa&rsquo; kita kepada guru kita&nbsp;</p>\r\n\r\n<p>الله يوفقكم و يبارك فيكم&nbsp;<br />\r\nSemoga kita mendapatkan keberkahan daripada guru semua , Amiiiiiinnn</p>\r\n\r\n<p>SHARE&nbsp;SERENTAK</p>','19/10/2024 - 20/10/2024','2024-10-20','2024-10-19','MultaqoSanawi8','Pondok Pesantren Darussa\'adah Gubugklakah','image/event/tVDBRL8EjyOMjxEoZNYLKIYuZjxRHf2eGC1leWxX.jpg','1',NULL,'2024-10-15 01:24:11','Rp. 150.000'),
(12,'Cek','<p>percobaan</p>','06/08/2025 - 07/08/2025','2025-08-07','2025-08-06','','Mboh','image/event/7eZ64S0wu1y6aJ3UHCu2tLgKCyKe0BnhfhYDBIMr.png','0',NULL,'2025-09-18 07:15:27','Rp. 1.000'),
(13,'Tes','<p>Tes</p>','11/10/2025 - 12/10/2025','2025-10-12','2025-10-11','','Tes',NULL,'0',NULL,'2025-10-10 07:48:40','Rp. 159'),
(14,'Multaqo Sanawi 9','<p>Multaqo Sanawi 9</p>','11/10/2025 - 12/10/2025','2025-10-12','2025-10-11','MultaqoSanawi9','Pondok Pesantren Darussa\'adah Gubugklakah','image/event/KHQ3CGTeEA0nWcq3mDyYa2AzBMSlQ2MTjppG0Bi0.jpg','1',NULL,NULL,'Rp. 150.000'),
(15,'Multaqo Sanawi 9','<p>Hadirilah! Multaqo Sanawi 9 yang akan diselenggarakan pada tanggal 11 - 12 Oktober 2025. Berlokasi di Pondok Pesantren Darussaadah Gubugklakah. Mari semarakkan acara reuni akbar tahunan alumni Pondok Pesantren Darussaadah Gubugklakah!</p>','11/10/2025 - 12/10/2025','2025-10-12','2025-10-11','','Pondok Pesantren Darussa\'adah Gubugklakah','image/event/nFpc1xzumbfJYk3H3jHoWulLLgVvbsbk2pFviO3H.jpg','0',NULL,'2025-10-10 18:36:32','Rp. 150.000'),
